// x509-verify-chain, Go: crypto/x509's ParseCertificate and Verify over
// the input of mk/x509-verify-chain.mk's comment (the same three DER
// certificates, the same time and host, serverAuth). Built with GOAMD64=v2
// -pgo=off.
package main

import (
	"crypto/x509"
	"encoding/hex"
	"fmt"
	"os"
	"strconv"
	"time"
)

const (
	leafHex  = ""
	interHex = ""
	rootHex  = ""
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: x509-verify-chain <reps>")
		os.Exit(2)
	}
	reps, _ := strconv.Atoi(os.Args[1])
	leaf, _ := hex.DecodeString(leafHex)
	inter, _ := hex.DecodeString(interHex)
	root, _ := hex.DecodeString(rootHex)
	now := time.Unix(1704067200, 0)
	ok := 0
	for i := 0; i < reps; i++ {
		l, err1 := x509.ParseCertificate(leaf)
		m, err2 := x509.ParseCertificate(inter)
		r, err3 := x509.ParseCertificate(root)
		if err1 != nil || err2 != nil || err3 != nil {
			panic("parse")
		}
		roots, inters := x509.NewCertPool(), x509.NewCertPool()
		roots.AddCert(r)
		inters.AddCert(m)
		if _, err := l.Verify(x509.VerifyOptions{DNSName: "example.test", Roots: roots, Intermediates: inters, CurrentTime: now, KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}}); err == nil {
			ok++
		}
	}
	fmt.Println(ok)
}
